INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(124736, 'ruRU', '', 'Я иду!', 24330),
(124741, 'ruRU', '', 'Да, Ксайлем немного сошёл с ума, но он всё же прославленный архимаг! Только подумай, чему я мог бы у него научиться!', 24330),
(124743, 'ruRU', '', 'Один из учеников ближнего круга сказал мне: "Нужно овладеть традиционными школами, прежде чем погружаться в царство тени."\n\nДумаю, это должно было быть подсказкой.', 24330),
(124744, 'ruRU', '', 'У меня раньше был неплохой наряд, как у тебя, но я устал от того, что другие ученики постоянно вызывают меня на дуэль.\n\nЯ уверен, Ксайлем впустит меня в башню благодаря моему мастерству колдовства!', 24330),
(124745, 'ruRU', '', 'Я однажды видел, как один из учеников входил внутрь, хотя всё, что я смог заметить — он активировал белый самоцвет раньше красного.', 24330),
(124752, 'ruRU', '', 'Что бы ты ни делал, не пытайся трогать эти самоцветы, если не знаешь правильного порядка.\n\nЯ видел, что случается, когда трогаешь неправильный, и зрелище не из приятных.', 24330),
(124753, 'ruRU', '', 'Я? Понятия не имею. Просто не слушай ничего из того, что говорит Викс.\n\nОн получает какое-то больное удовольствие, наблюдая, как ученики поджаривают сами себя на этой головоломке.', 24330),
(124761, 'ruRU', '', 'Ступай осторожно, присутствие Легиона здесь сильно.$b$bНеужели Ночнорождённые забыли всё, что мы потеряли в Войне древних? На этом пути лежат разрушение и смерть.', 24330),
(124764, 'ruRU', '', 'Легион здесь силён. Старайся не привлекать ненужного внимания, $r.', 24330),
(124772, 'ruRU', '', 'Отвратительная демоническая мразь не прикоснётся к моим девочкам.', 24330),
(124774, 'ruRU', '', 'Хватай бездельничать, или заставлю тебя пройти по доске!', 24330),
(124775, 'ruRU', '', 'Вернись к работе, огр! За что мы тебе платим?', 24330),
(124776, 'ruRU', '', 'Вы, негодники, хоть раз в море-то бывали?!', 24330),
(124809, 'ruRU', '', 'Его портал нестабилен, но его отголосок остаётся.', 24330),
(124810, 'ruRU', '', 'Это потребует времени, но мы, возможно, сможем использовать его, чтобы добраться до него.', 24330),
(124811, 'ruRU', '', 'У меня последняя просьба, $c. Хотя Ксайлем, вероятно, не станет сдерживаться, прошу, пощади его жизнь.', 24330),
(124812, 'ruRU', '', 'Я верю, что добрый человек, которым был архимаг Ксайлем, всё ещё существует под этим безумием.', 24330),
(124813, 'ruRU', '', '%s жестом приглашает тебя следовать.', 24330),
(124816, 'ruRU', '', 'Временная блокировка разрушена! Они свободны!', 24330),
(124817, 'ruRU', '', 'Отсюда у нас есть доступ к территории дворца. Мы можем открыть ворота изнутри!', 24330),
(124818, 'ruRU', '', 'Щупальца силы исходят от этой аномалии. Полагаю, Элизанда использует это существо, чтобы поддерживать заклинание временной блокировки.', 24330),
(124819, 'ruRU', '', 'Чтобы освободить наших союзников у ворот, эту мерзость нужно уничтожить!', 24330),
(124823, 'ruRU', '', 'Вождь даровал мне этот пост, чтобы изучать птиц нашего региона, чтобы мы могли лучше использовать их для доставки сообщений на большие расстояния. Благодаря такому центральному расположению рядом с торговыми узлами Орды мне удалось собрать довольно крупный зверинец экзотических видов. Хочешь испытать свою удачу против них?', 24330),
(124824, 'ruRU', '', 'Правосудие льётся сверху!', 24330),
(124825, 'ruRU', '', 'Не падай духом, в следующий раз получится лучше!', 24330),
(124826, 'ruRU', '', 'Ты победил на крыле и молитве!', 24330),
(124827, 'ruRU', '', 'Налетай!', 24330),
(124828, 'ruRU', '', 'Это перьевое буйство!', 24330),
(124829, 'ruRU', '', 'Эту вычёркиваем.', 24330),
(124831, 'ruRU', '', 'Столько всего изменилось для меня с тех пор, как ты принёс тот плод.$b$bЯ очень тоскую по своему брату, но знаю, почему он отдал себя этому делу.$b$bЕсть кое-что, о чём я должен попросить тебя. Мне нужно отплатить остальным за их доброту. Мне нужно отомстить за смерть своего брата.$b$bПрошу, отведи меня к Первому Чародею, чтобы я мог посвятить себя её делу.', 24330),
(124848, 'ruRU', '', '<Раненая матриарх прятала себя, пока не почуяла запах своего потерянного птенца. Однако она слишком тяжело ранена, чтобы заботиться о нём.>', 24330),
(124850, 'ruRU', '', 'Ты слишком поздно! Ритуал почти завершён.', 24330),
(124851, 'ruRU', '', 'Скоро Канретад снова будет среди нас!', 24330),
(124862, 'ruRU', '', 'Я никогда не понимала, насколько сильно мы зависели от Ночного Колодца. Избавиться от его зова — это... освобождает.', 26972),
(124863, 'ruRU', '', 'Ох, как же приятно снова чувствовать себя собой прежней.$B$B<Вальтруа нежно проводит тыльной стороной ладони по своей высокой скуле.>$B$BКак видишь, мана прекрасно действует на кожу!', 26972),
(124865, 'ruRU', '', 'Должна признать, мне довольно любопытно исследовать мир за пределами Сурамара.$B$BПримитивные культуры всегда меня увлекали!', 26972),
(124866, 'ruRU', '', 'Мы должны держать Канретада изгнанным, чего бы это ни стоило.', 24330),
(124869, 'ruRU', '', 'Он когда-то занимал твою должность, Повелитель Пустоты. Канретад был основателем нашего совета.\n\nОн собрал нас вместе, несмотря на наши разногласия, и вёл нас в погоне за большей силой, чем мы когда-либо знали.\n\nОднако для него этого никогда не было достаточно. После гибели Иллидана в Чёрном храме Канретад стал одержим силами, что он там увидел. Он хотел контролировать демонические энергии так же, как это делал Иллидан, и был готов сделать это любой ценой.\n\nЯ дал клятву Канретаду, что если он будет потерян силам, которые пытался контролировать, я изгоню его. Это клятва, которую я должен сдержать, ради него и ради всех остальных.', 24330),
(124870, 'ruRU', '', 'Ох, всё хорошо, дорогуша. Мне не нужен никто, чтобы повторять со мной реплики. Я уже неплохо их выучила.', 24330),
(124871, 'ruRU', '', 'Все без ума от этих, ох, таких "умных" пересказов. Никто больше не ценит классику!', 24330);
